parameters.jsCode:
const rows = $input.all().map(item => item.json);
const groupedByUser = {};

for (const row of rows) {
  const userId = row.user_id;

  if (!groupedByUser[userId]) {
    groupedByUser[userId] = {
      user_id: userId,
      destination_chat_id: row.destination_chat_id,
      risk_profile: row.risk_profile,
      distance_to_river: row.distance_to_river,
      location_lat: row.location_lat,
      location_lng: row.location_lng,
      queue_ids: [],
      sensors: []
    };
  }

  if (!groupedByUser[userId].location_lat && row.location_lat) {
    groupedByUser[userId].location_lat = row.location_lat;
  }
  if (!groupedByUser[userId].location_lng && row.location_lng) {
    groupedByUser[userId].location_lng = row.location_lng;
  }

  groupedByUser[userId].queue_ids.push(row.queue_id);

  // MASUKKAN DI SINI: Bungkus data spasial spesifik terhadap alat sensor tersebut
  groupedByUser[userId].sensors.push({
    sensor_id: row.sensor_id,
    pos_name: row.pos_name,
    sensor_type: row.sensor_type,
    current_value: row.current_value,
    current_warning_level: row.current_warning_level,
    previous_warning_level: row.previous_warning_level,
    trend_3h: row.trend_3h,
    measured_at: row.measured_at,
    // Dua baris ini wajib diloloskan:
    sensor_distance_km: row.sensor_distance_km,
    sensor_elevation_diff: row.sensor_elevation_diff
  });
}

return Object.keys(groupedByUser).map(userId => ({
  json: groupedByUser[userId]
}));

