// 1. Ambil data mentah dari node sebelumnya
const user = $('If').item.json;
const weatherNode = $('HTTP Request').item.json;

// 2. Kamus Resmi Kode Cuaca WMO Open-Meteo
const wmoCodes = {
  0: "Cerah (Clear sky)",
  1: "Cerah Berawan (Mainly clear)",
  2: "Berawan Sebagian (Partly cloudy)",
  3: "Mendung Total (Overcast)",
  45: "Kabut (Fog)",
  48: "Kabut Rime (Depositing rime fog)",
  51: "Gerimis Ringan (Light drizzle)",
  53: "Gerimis Sedang (Moderate drizzle)",
  55: "Gerimis Lebat (Dense drizzle)",
  56: "Gerimis Membeku Ringan",
  57: "Gerimis Membeku Lebat",
  61: "Hujan Intensitas Ringan (Slight rain)",
  63: "Hujan Intensitas Sedang (Moderate rain)",
  65: "Hujan Lebat/Sangat Deras (Heavy rain)",
  66: "Hujan Membeku Ringan",
  67: "Hujan Membeku Lebat",
  71: "Hujan Salju Ringan",
  73: "Hujan Salju Sedang",
  75: "Hujan Salju Lebat",
  77: "Butiran Salju",
  80: "Hujan Pancar Ringan (Slight rain showers)",
  81: "Hujan Pancar Sedang (Moderate rain showers)",
  82: "Hujan Pancar Ekstrim/Sangat Deras (Violent rain showers)",
  85: "Hujan Badai Salju Ringan",
  86: "Hujan Badai Salju Lebat",
  95: "Hujan Badai Disertai Petir (Thunderstorm)",
  96: "Hujan Badai Petir Es Ringan",
  99: "Hujan Badai Petir Es Lebat"
};

// 3. Saring Sensor (Ambil kondisi paling terbaru per sensor_id)
const latestSensors = {};
for (const s of user.sensors) {
  if (!latestSensors[s.sensor_id] || new Date(s.measured_at) > new Date(latestSensors[s.sensor_id].measured_at)) {
    latestSensors[s.sensor_id] = s;
  }
}

// 4. Terjemahkan Data Cuaca secara Dinamis
let weatherString = "Data cuaca tidak tersedia.";
if (weatherNode && weatherNode.current) {
  const rainAmt = weatherNode.current.rain;
  const code = weatherNode.current.weather_code;
  const weatherDesc = wmoCodes[code] || "Hujan/Berawan"; 
  weatherString = `Kondisi: ${weatherDesc}, Curah Hujan Lokal: ${rainAmt} mm`;
}

// 5. Kembalikan Payload Bersih Siap Konsumsi untuk OpenAI
return {
  json: {
    destination_chat_id: user.destination_chat_id,
    risk_profile: user.risk_profile,
    distance_to_river_m: (user.distance_to_river * 1000).toFixed(0),
    weather_info: weatherString,
    processed_sensors: Object.values(latestSensors)
  }
};

const rows = $input.all().map(item => item.json);
const grouped = {};

for (const row of rows) {
  const communityId = row.community_id;

  if (!grouped[communityId]) {
    grouped[communityId] = {
      community_id: communityId,
      community_name: row.community_name,
      destination_chat_id: row.destination_chat_id,
      telegram_group_title: row.telegram_group_title,
      queue_ids: [],
      sensors: [],
    };
  }

  grouped[communityId].queue_ids.push(row.queue_id);

  grouped[communityId].sensors.push({
    sensor_id: row.sensor_id,
    pos_name: row.pos_name,
    sensor_type: row.sensor_type,
    old_level: Number(row.old_level),
    new_level: Number(row.new_level),
    value: row.value,
    trend_3h: row.trend_3h || 'stabil',
    measured_at: row.measured_at,
  });
}

return Object.values(grouped).map(item => ({ json: item }));

const data = $input.item.json;

const levelText = (n) => ['Normal', 'Siaga 3', 'Siaga 2', 'Siaga 1'][Number(n)] ?? '?';
const levelEmoji = (n) => ['🟢', '🟡', '🟠', '🔴'][Number(n)] ?? '⚪';

function formatWib(iso) {
  if (!iso) return '-';
  return new Date(iso).toLocaleString('id-ID', {
    timeZone: 'Asia/Jakarta',
    dateStyle: 'medium',
    timeStyle: 'short',
  }) + ' WIB';
}

const latestBySensor = {};

for (const sensor of data.sensors) {
  const existing = latestBySensor[sensor.sensor_id];
  if (!existing || new Date(sensor.measured_at) > new Date(existing.measured_at)) {
    latestBySensor[sensor.sensor_id] = sensor;
  }
}

const sensors = Object.values(latestBySensor);

const lines = sensors.map((s) => {
  const trendIcon =
    s.trend_3h === 'naik' ? '⬆️' :
    s.trend_3h === 'turun' ? '⬇️' :
    '➡️';

  const unit = s.sensor_type === 'rf' ? 'mm/jam' : 'm';

  return `${levelEmoji(s.new_level)} *${s.pos_name}*\n` +
    `Status: ${levelText(s.old_level)} → ${levelText(s.new_level)}\n` +
    `Nilai: ${s.value} ${unit}\n` +
    `Trend 3 jam: ${trendIcon} ${s.trend_3h}\n` +
    `Waktu ukur: ${formatWib(s.measured_at)}`;
}).join('\n\n');

const text =
  `🚨 *ALERA FI : ALERT KOMUNITAS* 🚨\n\n` +
  `Terdapat perubahan status pos pantau untuk komunitas *${data.community_name || '-'}*:\n\n` +
  `${lines}\n\n` +
  `Mohon pantau kondisi lapangan dan koordinasikan dengan warga sekitar.\n\n` ;

return {
  json: {
    ...data,
    telegram_text: text,
  },
};
